  "pil.fulltitle": { en: "Five Fundamental Pillars", es: "Cinco Pilares Fundamentales", fr: "Cinq Piliers Fondamentaux", pt: "Cinco Pilares Fundamentais", de: "F\u00fcnf Grundlegende S\u00e4ulen", zh: "\u4e94\u5927\u57fa\u7840\u652f\u67f1", ar: "\u062e\u0645\u0633\u0629 \u0631\u0643\u0627\u0626\u0632 \u0623\u0633\u0627\u0633\u064a\u0629", th: "\u0e2b\u0e49\u0e32\u0e40\u0e2a\u0e32\u0e2b\u0e25\u0e31\u0e01\u0e1e\u0e37\u0e49\u0e19\u0e10\u0e32\u0e19" },
