  "prod.ai.subtitle": { en: "Intelligent Finance", es: "Finanzas Inteligentes", fr: "Finance Intelligente", pt: "Finan\u00e7as Inteligentes", de: "Intelligente Finanzen", zh: "\u667a\u80fd\u91d1\u878d", ar: "\u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0630\u0643\u064a", th: "\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e2d\u0e31\u0e08\u0e09\u0e23\u0e34\u0e22\u0e30" },
