  "prod.wallet.subtitle": { en: "Your Digital Financial Hub", es: "Tu Centro Financiero Digital", fr: "Votre Hub Financier Num\u00e9rique", pt: "Seu Hub Financeiro Digital", de: "Ihr Digitales Finanzzentrum", zh: "\u60a8\u7684\u6570\u5b57\u91d1\u878d\u4e2d\u5fc3", ar: "\u0645\u0631\u0643\u0632\u0643 \u0627\u0644\u0645\u0627\u0644\u064a \u0627\u0644\u0631\u0642\u0645\u064a", th: "\u0e28\u0e39\u0e19\u0e22\u0e4c\u0e01\u0e25\u0e32\u0e07\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25\u0e02\u0e2d\u0e07\u0e04\u0e38\u0e13" },
