  "why.innovation.desc": { en: "Blockchain + AI + Cryptography + Digital Finance.", es: "Blockchain + IA + Criptograf\u00eda + Finanzas Digitales.", fr: "Blockchain + IA + Cryptographie + Finances Num\u00e9riques.", pt: "Blockchain + IA + Criptografia + Finan\u00e7as Digitais.", de: "Blockchain + KI + Kryptografie + Digitale Finanzen.", zh: "\u533a\u5757\u94fe + AI + \u52a0\u5bc6\u672f + \u6570\u5b57\u91d1\u878d\u3002", ar: "\u0627\u0644\u0628\u0644\u0648\u0643\u062a\u0634\u064a\u0646 + \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a + \u0627\u0644\u062a\u0634\u0641\u064a\u0631 + \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0631\u0642\u0645\u064a.", th: "\u0e1a\u0e25\u0e47\u0e2d\u0e01\u0e40\u0e0a\u0e19 + AI + \u0e01\u0e32\u0e23\u0e40\u0e02\u0e49\u0e32\u0e23\u0e2b\u0e31\u0e2a + \u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19\u0e14\u0e34\u0e08\u0e34\u0e17\u0e31\u0e25" },
  "why.interop": { en: "Interoperability", es: "Interoperabilidad", fr: "Interop\u00e9rabilit\u00e9", pt: "Interoperabilidade", de: "Interoperabilit\u00e4t", zh: "\u4e92\u64cd\u4f5c\u6027", ar: "\u0627\u0644\u062a\u0634\u0627\u0628\u0643\u064a\u0629", th: "\u0e01\u0e32\u0e23\u0e17\u0e33\u0e07\u0e32\u0e19\u0e23\u0e48\u0e27\u0e21\u0e01\u0e31\u0e19" },
  "why.interop.desc": { en: "Connection between different networks and assets.", es: "Conexi\u00f3n entre diferentes redes y activos.", fr: "Connexion entre diff\u00e9rents r\u00e9seaux et actifs.", pt: "Conex\u00e3o entre diferentes redes e ativos.", de: "Verbindung zwischen verschiedenen Netzwerken und Assets.", zh: "\u4e0d\u540c\u7f51\u7edc\u548c\u8d44\u4ea7\u4e4b\u95f4\u7684\u8fde\u63a5\u3002", ar: "\u0627\u0644\u062a\u0631\u0627\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0634\u0628\u0643\u0627\u062a \u0648\u0627\u0644\u0623\u0635\u0648\u0644 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629.", th: "\u0e01\u0e32\u0e23\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e21\u0e15\u0e48\u0e2d\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\u0e40\u0e04\u0e23\u0e37\u0e2d\u0e02\u0e48\u0e32\u0e22\u0e41\u0e25\u0e30\u0e2a\u0e34\u0e19\u0e17\u0e23\u0e31\u0e1e\u0e22\u0e4c\u0e15\u0e48\u0e32\u0e07\u0e46" },
