  "road.node.asset": { en: "Digital Asset Management", es: "Gestión de Activos Digitales", fr: "Gestion d'Actifs Numériques", pt: "Gestão de Ativos Digitais", de: "Digitale Asset-Verwaltung", zh: "数字资产管理", ar: "إدارة الأصول الرقمية", th: "การจัดการสินทรัพย์ดิจิทัล" },
