  "road.p2.desc": { en: "Multichain expansion, new assets and institutional tool development.", es: "Expansión multichain, nuevos activos y desarrollo de herramientas institucionales.", fr: "Expansion multichaîne, nouveaux actifs et développement d'outils institutionnels.", pt: "Expansão multichain, novos ativos e desenvolvimento de ferramentas institucionais.", de: "Multichain-Expansion, neue Assets und Entwicklung institutioneller Werkzeuge.", zh: "多链扩展、新资产和机构工具开发。", ar: "التوسع متعدد السلاسل، أصول جديدة وتطوير أدوات مؤسسية.", th: "การขยายตัวหลายเชน สินทรัพย์ใหม่ และพัฒนาเครื่องมือสถาบัน" },
  "road.p3.title": { en: "Interoperability", es: "Interoperabilidad", fr: "Interopérabilité", pt: "Interoperabilidade", de: "Interoperabilität", zh: "互操作性", ar: "التشغيل البيني", th: "การทำงานร่วมกัน" },
  "road.p3.desc": { en: "Greater integration between networks, asset tokenization and complete digital financial services.", es: "Mayor integración entre redes, tokenización de activos y servicios financieros digitales completos.", fr: "Intégration accrue entre réseaux, tokenisation d'actifs et services financiers numériques complets.", pt: "Maior integração entre redes, tokenização de ativos e serviços financeiros digitais completos.", de: "Größere Integration zwischen Netzwerken, Asset-Tokenisierung und vollständige digitale Finanzdienstleistungen.", zh: "网络间更深度的整合、资产代币化和完整的数字金融服务。", ar: "تكامل أكبر بين الشبكات، توكنية الأصول وخدمات مالية رقمية كاملة.", th: "การบูรณาการที่มากขึ้นระหว่างเครือข่าย การทำโทเคนสินทรัพย์ และบริการทางการเงินดิจิทัลที่สมบูรณ์" },
  "road.p4.title": { en: "Global Digital Finance", es: "Finanzas Digitales Globales", fr: "Finance Numérique Mondiale", pt: "Finanças Digitais Globais", de: "Globale digitale Finanzierung", zh: "全球数字金融", ar: "التمويل الرقمي العالمي", th: "การเงินดิจิทัลระดับโลก" },
  "road.p4.desc": { en: "Progressive construction of a global, interoperable and accessible digital financial infrastructure.", es: "Construcción progresiva de una infraestructura financiera digital global, interoperable y accesible.", fr: "Construction progressive d'une infrastructure financière numérique mondiale, interopérable et accessible.", pt: "Construção progressiva de uma infraestrutura financeira digital global, interoperável e acessível.", de: "Fortschreitender Aufbau einer globalen, interoperablen und zugänglichen digitalen Finanzinfrastruktur.", zh: "逐步构建全球性、互操作且可访问的数字金融基础设施。", ar: "البناء التدريجي لبنية تحتية مالية رقمية عالمية وقابلة للتشغيل البيني ومتاحة.", th: "การสร้างโครงสร้างพื้นฐานทางการเงินดิจิทัลระดับโลกที่ทำงานร่วมกันและเข้าถึงได้" },
