  "prov.dex.uniswap.desc": { en: "Leading Ethereum DEX with direct integration to QFS ERC-20 contract for ETH network trading.", es: "DEX líder en Ethereum con integración directa al contrato QFS ERC-20 para trading en red ETH.", fr: "DEX Ethereum leader avec intégration directe au contrat QFS ERC-20 pour le trading sur le réseau ETH.", pt: "DEX líder no Ethereum com integração direta ao contrato QFS ERC-20 para negociação na rede ETH.", de: "Führende Ethereum-DEX mit direkter Integration in den QFS ERC-20 Vertrag für ETH-Netzwerk-Handel.", zh: "领先的以太坊DEX，直接集成QFS ERC-20合约，支持ETH网络交易。", ar: "DEX رائدة على Ethereum مع تكامل مباشر مع عقد QFS ERC-20 لتداول شبكة ETH.", th: "DEX ชั้นนำบน Ethereum ที่เชื่อมต่อกับสัญญา QFS ERC-20 โดยตรงสำหรับการซื้อขายบนเครือข่าย ETH" },
  "prov.dex.1inch.desc": { en: "DEX aggregator with direct QFS contract integration, finding the best trading prices across multiple platforms.", es: "Agregador DEX con integración directa de contratos QFS, encontrando los mejores precios de trading en múltiples plataformas.", fr: "Agrégateur DEX avec intégration directe des contrats QFS, trouvant les meilleurs prix de trading sur plusieurs plateformes.", pt: "Agregador DEX com integração direta de contratos QFS, encontrando os melhores preços de negociação em múltiplas plataformas.", de: "DEX-Aggregator mit direkter QFS-Vertragsintegration, der die besten Handelspreise über mehrere Plattformen findet.", zh: "DEX聚合器，直接集成QFS合约，在多个平台间寻找最佳交易价格。", ar: "مجمع DEX مع تكامل مباشر لعقود QFS، يجد أفضل أسعار التداول عبر منصات متعددة.", th: "ตัวรวม DEX ที่เชื่อมต่อกับสัญญา QFS โดยตรง ค้นหาราคาซื้อขายที่ดีที่สุดจากหลายแพลตฟอร์ม" },
  "prov.dex.sushi.desc": { en: "Multi-chain DEX with direct QFS contract integration and advanced DeFi features.", es: "DEX multi-cadena con integración directa de contratos QFS y funciones DeFi avanzadas.", fr: "DEX multi-chaînes avec intégration directe des contrats QFS et fonctionnalités DeFi avancées.", pt: "DEX multi-cadeia com integração direta de contratos QFS e recursos DeFi avançados.", de: "Multi-Chain-DEX mit direkter QFS-Vertragsintegration und erweiterten DeFi-Funktionen.", zh: "多链DEX，直接集成QFS合约，具备高级DeFi功能。", ar: "DEX متعددة السلاسل مع تكامل مباشر لعقود QFS وميزات DeFi المتقدمة.", th: "DEX หลายเชนที่เชื่อมต่อกับสัญญา QFS โดยตรงและมีฟีเจอร์ DeFi ขั้นสูง" },
  "prov.dex.balancer.desc": { en: "Automated portfolio manager and DEX with direct QFS contract integration.", es: "Gestor de cartera automatizado y DEX con integración directa de contratos QFS.", fr: "Gestionnaire de portefeuille automatisé et DEX avec intégration directe des contrats QFS.", pt: "Gerenciador de portfólio automatizado e DEX com integração direta de contratos QFS.", de: "Automatisierter Portfolio-Manager und DEX mit direkter QFS-Vertragsintegration.", zh: "自动化投资组合管理器和DEX，直接集成QFS合约。", ar: "مدير محفظة آلي و DEX مع تكامل مباشر لعقود QFS.", th: "ตัวจัดการพอร์ตโฟลิโออัตโนมัติและ DEX ที่เชื่อมต่อกับสัญญา QFS โดยตรง" },
  "prov.dex.curve.desc": { en: "Leading DEX for stablecoin trading with low slippage and direct QFS contract integration.", es: "DEX líder para trading de stablecoins con bajo slippage e integración directa de contratos QFS.", fr: "DEX leader pour le trading de stablecoins avec faible slippage et intégration directe des contrats QFS.", pt: "DEX líder para negociação de stablecoins com baixo slippage e integração direta de contratos QFS.", de: "Führende DEX für Stablecoin-Handel mit niedrigem Slippage und direkter QFS-Vertragsintegration.", zh: "领先的稳定币交易DEX，低滑点，直接集成QFS合约。", ar: "DEX رائدة لتداول العملات المستقرة مع انزلاق منخفض وتكامل مباشر لعقود QFS.", th: "DEX ชั้นนำสำหรับการซื้อขายสเตเบิลคอยน์ที่มีสไลปเพจต่ำและเชื่อมต่อกับสัญญา QFS โดยตรง" },
